import { randomUUID } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const DEFAULT_DATA_FILE = path.join(process.cwd(), 'data', 'books.json');

async function loadBooks(dataFile) {
  try {
    const raw = await readFile(dataFile, 'utf8');
    return JSON.parse(raw);
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function saveBooks(dataFile, books) {
  await mkdir(path.dirname(dataFile), { recursive: true });
  await writeFile(dataFile, JSON.stringify(books, null, 2));
}

export function createStore(dataFile = DEFAULT_DATA_FILE) {
  return {
    async list() {
      return loadBooks(dataFile);
    },

    async get(id) {
      const books = await loadBooks(dataFile);
      return books.find((b) => b.id === id) ?? null;
    },

    async add({ title, author, notes }) {
      const books = await loadBooks(dataFile);
      const book = {
        id: randomUUID(),
        title: title.trim(),
        author: author.trim(),
        notes: notes?.trim() ?? '',
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await saveBooks(dataFile, books);
      return book;
    },

    async update(id, changes) {
      const books = await loadBooks(dataFile);
      const book = books.find((b) => b.id === id);
      if (!book) return null;

      if (typeof changes.notes === 'string') book.notes = changes.notes.trim();
      if (typeof changes.title === 'string') book.title = changes.title.trim();
      if (typeof changes.author === 'string') book.author = changes.author.trim();
      if (changes.status === 'finished' && book.status !== 'finished') {
        book.status = 'finished';
        book.finishedAt = new Date().toISOString();
      } else if (changes.status === 'reading' && book.status !== 'reading') {
        book.status = 'reading';
        book.finishedAt = null;
      }

      await saveBooks(dataFile, books);
      return book;
    },
  };
}

