import express from 'express';
import path from 'node:path';
import { createStore } from './lib/store.js';

const app = express();
const store = createStore();

app.use(express.json());
app.use(express.static(path.join(process.cwd(), 'public')));

app.get('/api/books', async (req, res) => {
  res.json(await store.list());
});

app.post('/api/books', async (req, res) => {
  const { title, author, notes } = req.body ?? {};
  if (!title?.trim() || !author?.trim()) {
    return res.status(400).json({ error: 'title and author are required' });
  }
  const book = await store.add({ title, author, notes });
  res.status(201).json(book);
});

app.get('/api/books/:id', async (req, res) => {
  const book = await store.get(req.params.id);
  if (!book) return res.status(404).json({ error: 'not found' });
  res.json(book);
});

app.patch('/api/books/:id', async (req, res) => {
  const book = await store.update(req.params.id, req.body ?? {});
  if (!book) return res.status(404).json({ error: 'not found' });
  res.json(book);
});

app.get('/book/:id', (req, res) => {
  res.sendFile(path.join(process.cwd(), 'public', 'book.html'));
});

const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Reading tracker running at http://localhost:${port}`);
});

