:root {
  color-scheme: light dark;
  --border: #d8d8d8;
  --muted: #6b6b6b;
  --accent: #2b6cb0;
  --bg-card: #fafafa;
}

* {
  box-sizing: border-box;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  max-width: 680px;
  margin: 2rem auto;
  padding: 0 1.25rem;
  line-height: 1.5;
  color: #1a1a1a;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 0.25rem;
}

h2 {
  font-size: 1.05rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin: 2rem 0 0.75rem;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.book-card {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.75rem 1rem;
  background: var(--bg-card);
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
}

.book-card .title {
  font-weight: 600;
}

.book-card .author {
  color: var(--muted);
  font-size: 0.9rem;
}

.empty {
  color: var(--muted);
  font-style: italic;
}

form {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  margin-top: 2rem;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

label {
  font-size: 0.85rem;
  color: var(--muted);
  display: block;
  margin-bottom: 0.2rem;
}

input, textarea {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  font: inherit;
}

textarea {
  min-height: 4.5rem;
  resize: vertical;
}

button {
  align-self: flex-start;
  padding: 0.5rem 1.1rem;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: white;
  font: inherit;
  cursor: pointer;
}

button.secondary {
  background: transparent;
  color: var(--accent);
  border: 1px solid var(--accent);
}

button:hover {
  opacity: 0.9;
}

.back-link {
  display: inline-block;
  margin-bottom: 1rem;
}

.status-badge {
  font-size: 0.75rem;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  background: #e2e8f0;
  color: #333;
}

.status-badge.finished {
  background: #c6f6d5;
  color: #22543d;
}

.share-row {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  margin-top: 1rem;
}

.share-row input {
  flex: 1;
}

.error {
  color: #c53030;
  font-size: 0.9rem;
}

.actions {
  display: flex;
  gap: 0.5rem;
  margin-top: 1rem;
}

