function bookCard(book) {
  const li = document.createElement('li');
  li.className = 'book-card';
  const a = document.createElement('a');
  a.href = `/book/${book.id}`;
  a.innerHTML = `<span class="title">${escapeHtml(book.title)}</span> <span class="author">by ${escapeHtml(book.author)}</span>`;
  li.appendChild(a);
  return li;
}

function escapeHtml(str) {
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

function renderList(el, books, emptyText) {
  el.innerHTML = '';
  if (books.length === 0) {
    const li = document.createElement('li');
    li.className = 'empty';
    li.textContent = emptyText;
    el.appendChild(li);
    return;
  }
  for (const book of books) {
    el.appendChild(bookCard(book));
  }
}

async function loadBooks() {
  const res = await fetch('/api/books');
  const books = await res.json();
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');
  renderList(document.getElementById('reading-list'), reading, "Nothing yet — add a book below.");
  renderList(document.getElementById('finished-list'), finished, "No finished books yet.");
}

document.getElementById('add-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const form = e.target;
  const errorEl = document.getElementById('form-error');
  errorEl.hidden = true;

  const payload = {
    title: form.title.value,
    author: form.author.value,
    notes: form.notes.value,
  };

  const res = await fetch('/api/books', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    errorEl.textContent = body.error || 'Could not add book.';
    errorEl.hidden = false;
    return;
  }

  form.reset();
  loadBooks();
});

loadBooks();

