const id = window.location.pathname.split('/').pop();

async function load() {
  const res = await fetch(`/api/books/${id}`);
  if (!res.ok) {
    document.getElementById('not-found').hidden = false;
    return;
  }
  const book = await res.json();
  render(book);
}

function render(book) {
  document.getElementById('book-view').hidden = false;
  document.getElementById('book-title').textContent = book.title;
  document.getElementById('book-author').textContent = `by ${book.author}`;
  document.getElementById('book-notes').value = book.notes || '';

  const statusEl = document.getElementById('book-status');
  statusEl.textContent = book.status === 'finished' ? 'Finished' : 'Reading';
  statusEl.classList.toggle('finished', book.status === 'finished');

  const finishBtn = document.getElementById('finish-btn');
  finishBtn.hidden = book.status === 'finished';

  document.getElementById('share-url').value = window.location.href;
}

document.getElementById('notes-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const notes = document.getElementById('book-notes').value;
  const res = await fetch(`/api/books/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ notes }),
  });
  if (res.ok) render(await res.json());
});

document.getElementById('finish-btn').addEventListener('click', async () => {
  const res = await fetch(`/api/books/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status: 'finished' }),
  });
  if (res.ok) render(await res.json());
});

document.getElementById('copy-btn').addEventListener('click', async () => {
  const input = document.getElementById('share-url');
  input.select();
  try {
    await navigator.clipboard.writeText(input.value);
  } catch {
    document.execCommand('copy');
  }
});

load();

