import { mkdtemp, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createStore } from './store.js';

let dir;
let dataFile;
let store;

beforeEach(async () => {
  dir = await mkdtemp(path.join(os.tmpdir(), 'books-'));
  dataFile = path.join(dir, 'books.json');
  store = createStore(dataFile);
});

afterEach(async () => {
  await rm(dir, { recursive: true, force: true });
});

describe('store', () => {
  it('starts empty', async () => {
    expect(await store.list()).toEqual([]);
  });

  it('adds a book as currently reading', async () => {
    const book = await store.add({ title: ' Dune ', author: ' Frank Herbert ', notes: '' });
    expect(book.title).toBe('Dune');
    expect(book.author).toBe('Frank Herbert');
    expect(book.status).toBe('reading');
    expect(book.finishedAt).toBeNull();
    expect(await store.list()).toHaveLength(1);
  });

  it('persists across store instances (same file)', async () => {
    await store.add({ title: 'Dune', author: 'Frank Herbert' });
    const reopened = createStore(dataFile);
    expect(await reopened.list()).toHaveLength(1);
  });

  it('marks a book finished', async () => {
    const added = await store.add({ title: 'Dune', author: 'Frank Herbert' });
    const updated = await store.update(added.id, { status: 'finished' });
    expect(updated.status).toBe('finished');
    expect(updated.finishedAt).not.toBeNull();
  });

  it('updates notes', async () => {
    const added = await store.add({ title: 'Dune', author: 'Frank Herbert' });
    const updated = await store.update(added.id, { notes: 'great worldbuilding' });
    expect(updated.notes).toBe('great worldbuilding');
  });

  it('returns null when updating a missing book', async () => {
    expect(await store.update('nope', { notes: 'x' })).toBeNull();
  });
});

